const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');

const ShoppingCart = require('../src/cart');

describe('ShoppingCart', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  describe('constructor', () => {
    it('starts with no items and no discount', () => {
      assert.deepEqual(cart.items, []);
      assert.equal(cart.discount, 0);
      assert.equal(cart.getItemCount(), 0);
    });
  });

  describe('addItem', () => {
    it('adds a new item with its name, price and quantity', () => {
      cart.addItem('apple', 1.5, 2);
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1.5, quantity: 2 }]);
    });

    it('merges quantity when the same name is added again', () => {
      cart.addItem('apple', 1.5, 2);
      cart.addItem('apple', 1.5, 3);
      assert.equal(cart.getItemCount(), 1);
      assert.equal(cart.items[0].quantity, 5);
    });

    it('keeps the original price when a duplicate name is added with a different price', () => {
      cart.addItem('apple', 1.5, 1);
      cart.addItem('apple', 9.99, 1);
      assert.equal(cart.items[0].price, 1.5);
      assert.equal(cart.items[0].quantity, 2);
    });

    it('treats names case-sensitively', () => {
      cart.addItem('Apple', 1, 1);
      cart.addItem('apple', 1, 1);
      assert.equal(cart.getItemCount(), 2);
    });

    it('accepts a price of zero for free items', () => {
      cart.addItem('sticker', 0, 3);
      assert.equal(cart.getTotal(), 0);
      assert.equal(cart.getItemCount(), 1);
    });

    it('accepts a quantity of exactly one', () => {
      cart.addItem('pen', 2, 1);
      assert.equal(cart.items[0].quantity, 1);
    });

    it('rejects a zero quantity', () => {
      assert.throws(() => cart.addItem('pen', 2, 0), RangeError);
    });

    it('rejects a fractional quantity', () => {
      assert.throws(() => cart.addItem('pen', 2, 1.5), RangeError);
    });

    it('rejects an empty or whitespace-only name', () => {
      assert.throws(() => cart.addItem('', 1, 1), TypeError);
      assert.throws(() => cart.addItem('   ', 1, 1), TypeError);
    });

    it('rejects a non-string name', () => {
      assert.throws(() => cart.addItem(null, 1, 1), TypeError);
      assert.throws(() => cart.addItem(undefined, 1, 1), TypeError);
      assert.throws(() => cart.addItem(42, 1, 1), TypeError);
    });

    it('rejects a non-numeric price, including numeric strings', () => {
      assert.throws(() => cart.addItem('pen', '2', 1), TypeError);
      assert.throws(() => cart.addItem('pen', null, 1), TypeError);
      assert.throws(() => cart.addItem('pen', undefined, 1), TypeError);
    });

    it('rejects NaN and Infinity as price or quantity', () => {
      assert.throws(() => cart.addItem('pen', NaN, 1), TypeError);
      assert.throws(() => cart.addItem('pen', Infinity, 1), TypeError);
      assert.throws(() => cart.addItem('pen', 1, NaN), TypeError);
      assert.throws(() => cart.addItem('pen', 1, Infinity), TypeError);
    });

    it('rejects a missing quantity', () => {
      assert.throws(() => cart.addItem('pen', 2), TypeError);
    });

    it('includes the rejected value in the error message', () => {
      assert.throws(() => cart.addItem('pen', -3, 1), /-3/);
      assert.throws(() => cart.addItem('pen', 1, -4), /-4/);
    });
  });

  describe('removeItem', () => {
    it('removes only the named item and returns true', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 1);
      cart.addItem('cherry', 3, 1);

      assert.equal(cart.removeItem('banana'), true);
      assert.deepEqual(
        cart.items.map((i) => i.name),
        ['apple', 'cherry'],
      );
    });

    it('removes the whole line regardless of quantity', () => {
      cart.addItem('apple', 1, 10);
      cart.removeItem('apple');
      assert.equal(cart.getItemCount(), 0);
      assert.equal(cart.getTotal(), 0);
    });

    it('returns false for an item that is not in the cart', () => {
      cart.addItem('apple', 1, 1);
      assert.equal(cart.removeItem('ghost'), false);
      assert.equal(cart.getItemCount(), 1);
    });

    it('returns false when removing from an empty cart', () => {
      assert.equal(cart.removeItem('apple'), false);
      assert.equal(cart.getItemCount(), 0);
    });

    it('returns false when removing the same item twice', () => {
      cart.addItem('apple', 1, 1);
      assert.equal(cart.removeItem('apple'), true);
      assert.equal(cart.removeItem('apple'), false);
    });

    it('rejects a non-string name', () => {
      cart.addItem('apple', 1, 1);
      assert.throws(() => cart.removeItem(undefined), TypeError);
      assert.throws(() => cart.removeItem(null), TypeError);
      assert.throws(() => cart.removeItem(7), TypeError);
      assert.equal(cart.getItemCount(), 1);
    });
  });

  describe('getTotal', () => {
    it('returns 0 for an empty cart', () => {
      assert.equal(cart.getTotal(), 0);
    });

    it('returns price * quantity for a single item', () => {
      cart.addItem('apple', 2.5, 4);
      assert.equal(cart.getTotal(), 10);
    });

    it('sums every item in the cart', () => {
      cart.addItem('apple', 2, 3);
      cart.addItem('banana', 0.5, 4);
      cart.addItem('cherry', 10, 1);
      assert.equal(cart.getTotal(), 18);
    });

    it('applies a percentage discount by reducing the total', () => {
      cart.addItem('apple', 50, 2);
      cart.applyDiscount(25);
      assert.equal(cart.getTotal(), 75);
    });

    it('reflects items added after the discount was applied', () => {
      cart.applyDiscount(50);
      cart.addItem('apple', 10, 1);
      assert.equal(cart.getTotal(), 5);
      cart.addItem('banana', 10, 1);
      assert.equal(cart.getTotal(), 10);
    });

    it('does not modify the cart when called', () => {
      cart.addItem('apple', 2, 3);
      cart.applyDiscount(10);
      const before = structuredClone(cart.items);
      cart.getTotal();
      cart.getTotal();
      assert.deepEqual(cart.items, before);
      assert.equal(cart.discount, 10);
    });
  });

  describe('applyDiscount', () => {
    it('stores a valid percentage', () => {
      cart.applyDiscount(15);
      assert.equal(cart.discount, 15);
    });

    it('accepts the boundaries 0 and 100', () => {
      cart.addItem('apple', 40, 1);
      cart.applyDiscount(100);
      assert.equal(cart.getTotal(), 0);
      cart.applyDiscount(0);
      assert.equal(cart.getTotal(), 40);
    });

    it('accepts a fractional percentage', () => {
      cart.addItem('apple', 200, 1);
      cart.applyDiscount(12.5);
      assert.equal(cart.getTotal(), 175);
    });

    it('replaces rather than stacks a previous discount', () => {
      cart.addItem('apple', 100, 1);
      cart.applyDiscount(10);
      cart.applyDiscount(20);
      assert.equal(cart.getTotal(), 80);
    });

    it('rejects a discount just outside the range', () => {
      assert.throws(() => cart.applyDiscount(100.01), RangeError);
      assert.throws(() => cart.applyDiscount(-0.01), RangeError);
    });

    it('rejects non-numeric discounts, including numeric strings', () => {
      assert.throws(() => cart.applyDiscount('10'), TypeError);
      assert.throws(() => cart.applyDiscount(null), TypeError);
      assert.throws(() => cart.applyDiscount(undefined), TypeError);
      assert.throws(() => cart.applyDiscount(NaN), TypeError);
      assert.throws(() => cart.applyDiscount(Infinity), TypeError);
    });

    it('keeps the previous discount when a new value is rejected', () => {
      cart.addItem('apple', 100, 1);
      cart.applyDiscount(10);
      assert.throws(() => cart.applyDiscount(500), RangeError);
      assert.equal(cart.discount, 10);
      assert.equal(cart.getTotal(), 90);
    });
  });

  describe('getItemCount', () => {
    it('counts distinct items, not total quantity', () => {
      cart.addItem('apple', 1, 5);
      cart.addItem('banana', 1, 2);
      assert.equal(cart.getItemCount(), 2);
    });

    it('decreases after a removal', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 1, 1);
      cart.removeItem('apple');
      assert.equal(cart.getItemCount(), 1);
    });
  });

  // One block per original bug. Each test fails against the unfixed code.
  describe('regressions', () => {
    it('bug 1: addItem should reject a negative price', () => {
      assert.throws(() => cart.addItem('refund-hack', -10, 1), RangeError);
      assert.equal(cart.getItemCount(), 0);
    });

    it('bug 1: addItem should reject a negative quantity', () => {
      assert.throws(() => cart.addItem('apple', 1, -2), RangeError);
      assert.equal(cart.getItemCount(), 0);
    });

    it('bug 1: addItem should reject a negative quantity for an item already in the cart', () => {
      cart.addItem('apple', 1, 3);
      assert.throws(() => cart.addItem('apple', 1, -3), RangeError);
      assert.equal(cart.items[0].quantity, 3);
    });

    it('bug 2: removeItem should compare with === instead of assigning names', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 1);
      cart.removeItem('apple');
      assert.deepEqual(cart.items, [{ name: 'banana', price: 2, quantity: 1 }]);
    });

    it('bug 2: removeItem should report a missing item and leave the cart unchanged', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 1);
      const before = structuredClone(cart.items);
      assert.equal(cart.removeItem('ghost'), false);
      assert.deepEqual(cart.items, before);
    });

    it('bug 3: getTotal should not read past the last item', () => {
      cart.addItem('apple', 3, 2);
      assert.doesNotThrow(() => cart.getTotal());
      assert.equal(cart.getTotal(), 6);
    });

    it('bug 3: getTotal should return 0 for an empty cart instead of throwing', () => {
      assert.equal(cart.getTotal(), 0);
    });

    it('bug 4: getTotal should subtract the discount, not add it', () => {
      cart.addItem('apple', 100, 1);
      cart.applyDiscount(20);
      assert.equal(cart.getTotal(), 80);
    });

    it('bug 5: applyDiscount should reject a discount above 100', () => {
      assert.throws(() => cart.applyDiscount(150), RangeError);
      assert.equal(cart.discount, 0);
    });

    it('bug 5: applyDiscount should reject a negative discount', () => {
      assert.throws(() => cart.applyDiscount(-10), RangeError);
      assert.equal(cart.discount, 0);
    });
  });
});

