const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');

const ShoppingCart = require('../src/cart');

const EPSILON = 1e-9;

function assertClose(actual, expected) {
  assert.ok(
    Math.abs(actual - expected) < EPSILON,
    `expected ${actual} to be within ${EPSILON} of ${expected}`,
  );
}

describe('ShoppingCart edge cases', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  describe('unicode and unusual names', () => {
    it('adds and removes items with non-ASCII names', () => {
      cart.addItem('café', 3, 1);
      cart.addItem('🍎', 1, 2);
      cart.addItem('日本茶', 5, 1);
      assert.equal(cart.getTotal(), 10);
      assert.equal(cart.removeItem('🍎'), true);
      assert.deepEqual(
        cart.items.map((i) => i.name),
        ['café', '日本茶'],
      );
    });

    it('treats differently normalized unicode names as distinct items', () => {
      const composed = 'café';
      const decomposed = 'café';
      cart.addItem(composed, 1, 1);
      cart.addItem(decomposed, 1, 1);
      assert.equal(cart.getItemCount(), 2);
    });

    it('treats names with surrounding whitespace as distinct from the trimmed name', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem(' apple ', 1, 1);
      assert.equal(cart.getItemCount(), 2);
      assert.equal(cart.removeItem('apple'), true);
      assert.equal(cart.items[0].name, ' apple ');
    });

    it('rejects names made only of unicode whitespace', () => {
      assert.throws(() => cart.addItem(' \t\n', 1, 1), TypeError);
    });

    it('accepts a very long name', () => {
      const longName = 'x'.repeat(10_000);
      cart.addItem(longName, 1, 1);
      assert.equal(cart.removeItem(longName), true);
    });

    it('returns false when removing an empty string', () => {
      cart.addItem('apple', 1, 1);
      assert.equal(cart.removeItem(''), false);
      assert.equal(cart.getItemCount(), 1);
    });
  });

  describe('numeric boundaries', () => {
    it('accepts negative zero as a price', () => {
      cart.addItem('free', -0, 1);
      assert.equal(cart.getTotal(), 0);
    });

    it('accepts Number.MAX_SAFE_INTEGER as a quantity', () => {
      cart.addItem('bolt', 0, Number.MAX_SAFE_INTEGER);
      assert.equal(cart.items[0].quantity, Number.MAX_SAFE_INTEGER);
    });

    it('rejects a merge that would push quantity past Number.MAX_SAFE_INTEGER and keeps the old quantity', () => {
      cart.addItem('bolt', 0, Number.MAX_SAFE_INTEGER);
      assert.throws(() => cart.addItem('bolt', 0, 1), RangeError);
      assert.equal(cart.items[0].quantity, Number.MAX_SAFE_INTEGER);
    });

    it('rejects a quantity above Number.MAX_SAFE_INTEGER', () => {
      assert.throws(() => cart.addItem('bolt', 1, Number.MAX_SAFE_INTEGER + 2), RangeError);
    });

    it('rejects the smallest negative price', () => {
      assert.throws(() => cart.addItem('pen', -Number.MIN_VALUE, 1), RangeError);
    });

    it('accepts a tiny positive discount and negative zero discount', () => {
      cart.addItem('apple', 100, 1);
      cart.applyDiscount(1e-10);
      assertClose(cart.getTotal(), 100);
      cart.applyDiscount(-0);
      assert.equal(cart.getTotal(), 100);
    });

    it('keeps floating-point totals within rounding error for fractional prices', () => {
      cart.addItem('a', 0.1, 1);
      cart.addItem('b', 0.2, 1);
      assertClose(cart.getTotal(), 0.3);
    });

    it('applies a discount to fractional totals within rounding error', () => {
      cart.addItem('coffee', 19.99, 3);
      cart.applyDiscount(15);
      assertClose(cart.getTotal(), 50.9745);
    });
  });

  describe('hostile or unexpected input types', () => {
