const { describe, it } = require('node:test');
const assert = require('node:assert/strict');

const ShoppingCart = require('../src/cart');

describe('ShoppingCart workflows', () => {
  it('runs a full checkout: add, merge, remove, discount, total', () => {
    const cart = new ShoppingCart();
    cart.addItem('shirt', 20, 2);
    cart.addItem('socks', 5, 3);
    cart.addItem('shirt', 20, 1);
    cart.addItem('hat', 15, 1);

    assert.equal(cart.getItemCount(), 3);
    assert.equal(cart.getTotal(), 90);

    assert.equal(cart.removeItem('hat'), true);
    assert.equal(cart.getTotal(), 75);

    cart.applyDiscount(20);
    assert.equal(cart.getTotal(), 60);
    assert.deepEqual(cart.items, [
      { name: 'shirt', price: 20, quantity: 3 },
      { name: 'socks', price: 5, quantity: 3 },
    ]);
  });

  it('uses the new price when an item is removed and added again', () => {
    const cart = new ShoppingCart();
    cart.addItem('book', 10, 1);
    cart.removeItem('book');
    cart.addItem('book', 12, 1);
    assert.equal(cart.getTotal(), 12);
  });

  it('keeps the discount after the cart is emptied and applies it to new items', () => {
    const cart = new ShoppingCart();
    cart.applyDiscount(10);
    cart.addItem('lamp', 50, 1);
    cart.removeItem('lamp');
    assert.equal(cart.getTotal(), 0);
    cart.addItem('desk', 200, 1);
    assert.equal(cart.getTotal(), 180);
  });

  it('ends in the same state as the valid-only sequence when invalid calls are mixed in', () => {
    const valid = new ShoppingCart();
    valid.addItem('a', 1, 2);
    valid.addItem('b', 3, 1);
    valid.applyDiscount(50);
    valid.removeItem('a');

    const mixed = new ShoppingCart();
    mixed.addItem('a', 1, 2);
    assert.throws(() => mixed.addItem('a', 1, -2));
    mixed.addItem('b', 3, 1);
    assert.throws(() => mixed.addItem('c', -3, 1));
    mixed.applyDiscount(50);
    assert.throws(() => mixed.applyDiscount(101));
    assert.equal(mixed.removeItem('missing'), false);
    mixed.removeItem('a');

    assert.deepEqual(mixed.items, valid.items);
    assert.equal(mixed.discount, valid.discount);
    assert.equal(mixed.getTotal(), valid.getTotal());
  });

  describe('isolation between carts', () => {
    it('does not share items between instances', () => {
      const first = new ShoppingCart();
      const second = new ShoppingCart();
      first.addItem('apple', 1, 1);
      assert.equal(second.getItemCount(), 0);
      assert.notEqual(first.items, second.items);
    });

    it('does not share discounts between instances', () => {
      const first = new ShoppingCart();
      const second = new ShoppingCart();
      first.addItem('apple', 100, 1);
      second.addItem('apple', 100, 1);
      first.applyDiscount(30);
      assert.equal(first.getTotal(), 70);
      assert.equal(second.getTotal(), 100);
    });

    it('does not affect other carts when one removes an item', () => {
      const first = new ShoppingCart();
      const second = new ShoppingCart();
      first.addItem('apple', 1, 1);
      second.addItem('apple', 1, 1);
      first.removeItem('apple');
      assert.equal(second.getItemCount(), 1);
    });
  });

  it('keeps a consistent total when concurrent async tasks share one cart', async () => {
    const cart = new ShoppingCart();
    const shopper = async (id) => {
      for (let n = 0; n < 50; n++) {
        cart.addItem(`shopper-${id}`, 2, 1);
        await Promise.resolve();
      }
    };
    await Promise.all([1, 2, 3, 4].map(shopper));
    assert.equal(cart.getItemCount(), 4);
    assert.ok(cart.items.every((i) => i.quantity === 50));
    assert.equal(cart.getTotal(), 4 * 50 * 2);
  });
});

