ROOT=/tmp/cart-bench/mutants && rm -rf "$ROOT" && mkdir -p "$ROOT" && node - "$ROOT" <<'EOF'
const fs = require('node:fs');
const path = require('node:path');
const root = process.argv[2];
const src = fs.readFileSync('src/cart.js', 'utf8');
const mutants = {
  1: [['if (price < 0) {', 'if (false) {'], ['!Number.isSafeInteger(quantity) || quantity < 1', '!Number.isSafeInteger(Math.abs(quantity))']],
  2: [[/removeItem\(name\) \{[\s\S]*?\n  \}\n/, 'removeItem(name) {\n    this.items = this.items.filter(i => i.name = name);\n  }\n']],
  3: [['const subtotal = this.items.reduce((sum, i) => sum + i.price * i.quantity, 0);',
       'let subtotal = 0;\n    for (let i = 0; i <= this.items.length; i++) { subtotal += this.items[i].price * this.items[i].quantity; }']],
  4: [['subtotal - (subtotal * this.discount) / 100', 'subtotal + (subtotal * this.discount) / 100']],
  5: [['percent < MIN_DISCOUNT_PERCENT || percent > MAX_DISCOUNT_PERCENT', 'false']],
};
for (const [n, edits] of Object.entries(mutants)) {
  let out = src;
  for (const [from, to] of edits) {
    const next = out.replace(from, to);
    if (next === out) throw new Error(`mutant ${n}: pattern not found: ${from}`);
    out = next;
  }
  const dir = path.join(root, `bug${n}`);
  fs.mkdirSync(path.join(dir, 'src'), { recursive: true });
  fs.cpSync('tests', path.join(dir, 'tests'), { recursive: true });
  fs.writeFileSync(path.join(dir, 'src/cart.js'), out);
}
EOF
for n in 1 2 3 4 5; do
  failing=$(cd "$ROOT/bug$n" && node --test --test-reporter=tap tests/cart.test.js 2>&1 | grep -E '^        not ok .* - bug [0-9]' | sed -E 's/.* - (bug [0-9]).*/\1/' | sort | uniq -c | tr '\n' ' ')
  total=$(cd "$ROOT/bug$n" && node --test --test-reporter=tap tests/ 2>/dev/null | grep -E '^# fail' ; cd "$ROOT/bug$n" && node --test --test-reporter=tap 'tests/**/*.test.js' 2>&1 | grep -E '^# fail')
  echo "mutant bug$n -> failing regression tests: [$failing] | suite $total"
done

