const MIN_DISCOUNT_PERCENT = 0;
const MAX_DISCOUNT_PERCENT = 100;

// Objects are reported by type only: stringifying them could throw
// (circular refs, null prototype) or run caller-defined toString.
function describeValue(value) {
  if (typeof value === 'string') {
    return JSON.stringify(value);
  }
  if (value !== null && (typeof value === 'object' || typeof value === 'function')) {
    return `a value of type ${typeof value}`;
  }
  return String(value);
}

function assertFiniteNumber(value, label) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(`${label} must be a finite number, received ${describeValue(value)}`);
  }
}

function assertString(value, label) {
  if (typeof value !== 'string') {
    throw new TypeError(`${label} must be a string, received ${describeValue(value)}`);
  }
}

/**
 * In-memory shopping cart. Items are keyed by exact, case-sensitive name.
 * Every mutating method validates its input before changing state, so a
 * rejected call leaves the cart as it was.
 */
class ShoppingCart {
  constructor() {
    /** @type {{ name: string, price: number, quantity: number }[]} */
    this.items = [];
    /** Percentage in [0, 100]. */
    this.discount = 0;
  }

  /**
   * Adds an item, or increases the quantity of an item already in the cart.
   * A repeat add keeps the price recorded by the first add.
   *
   * @param {string} name non-blank item name
   * @param {number} price unit price, >= 0 (0 allows free items)
   * @param {number} quantity positive safe integer
   * @throws {TypeError} name is not a non-blank string, or price/quantity is not a finite number
   * @throws {RangeError} price is negative, quantity is not a positive safe integer,
   *   or the merged quantity would exceed Number.MAX_SAFE_INTEGER
   */
  addItem(name, price, quantity) {
    assertString(name, 'name');
    if (name.trim() === '') {
      throw new TypeError(`name must not be blank, received ${describeValue(name)}`);
    }
    assertFiniteNumber(price, 'price');
    assertFiniteNumber(quantity, 'quantity');
    if (price < 0) {
      throw new RangeError(`price must be >= 0, received ${price}`);
    }
    if (!Number.isSafeInteger(quantity) || quantity < 1) {
      throw new RangeError(
        `quantity must be a positive integer no greater than ${Number.MAX_SAFE_INTEGER}, received ${quantity}`,
      );
    }

    const existing = this.items.find((i) => i.name === name);
    if (existing) {
      const merged = existing.quantity + quantity;
      if (!Number.isSafeInteger(merged)) {
        throw new RangeError(`quantity for "${name}" would exceed ${Number.MAX_SAFE_INTEGER}`);
      }
      existing.quantity = merged;
    } else {
      this.items.push({ name, price, quantity });
    }
  }

  /**
   * Removes an item line, whatever its quantity.
   *
   * @param {string} name
   * @returns {boolean} true if the item was removed, false if it was not in the cart
   * @throws {TypeError} name is not a string
   */
  removeItem(name) {
    assertString(name, 'name');
    const index = this.items.findIndex((i) => i.name === name);
    if (index === -1) {
      return false;
    }
    this.items.splice(index, 1);
    return true;
  }

  /**
   * @returns {number} sum of price * quantity, reduced by the current discount.
   *   Not rounded; format for display at the call site.
   */
  getTotal() {
    const subtotal = this.items.reduce((sum, i) => sum + i.price * i.quantity, 0);
    return subtotal - (subtotal * this.discount) / 100;
  }

  /**
   * Sets the cart-wide percentage discount, replacing any previous one.
   *
   * @param {number} percent value in [0, 100]
   * @throws {TypeError} percent is not a finite number
   * @throws {RangeError} percent is outside [0, 100]; the previous discount is kept
   */
  applyDiscount(percent) {
    assertFiniteNumber(percent, 'discount');
    if (percent < MIN_DISCOUNT_PERCENT || percent > MAX_DISCOUNT_PERCENT) {
      throw new RangeError(
        `discount must be between ${MIN_DISCOUNT_PERCENT} and ${MAX_DISCOUNT_PERCENT}, received ${percent}`,
      );
    }
    this.discount = percent;
  }

  /** @returns {number} number of distinct items, not the sum of quantities */
  getItemCount() {
    return this.items.length;
  }
}

module.exports = ShoppingCart;
